import { Thread, Threads } from "@amodx/threads/";
import { TasksIds } from "../../Tasks/TasksIds.js";
import { setLocationData } from "../../Util/LocationData";
class TaskQueue {
    _task;
    _queue = [];
    constructor(_task) {
        this._task = _task;
    }
    add(data) {
        this._queue.push(data);
    }
    clear() {
        this._queue.length = 0;
    }
    run() {
        return new Promise((resolve) => {
            let waitingFor = 0;
            const onDone = () => {
                waitingFor--;
                if (waitingFor <= 0)
                    resolve(true);
            };
            while (this._queue.length) {
                const data = this._queue.shift();
                waitingFor++;
                this._task.run(data, null, onDone);
            }
        });
    }
}
export class LocationTaskToolTask {
    id;
    _count = 0;
    _threads;
    constructor(id, threads) {
        this.id = id;
        if (threads instanceof Thread) {
            this._threads = [threads];
        }
        else {
            this._threads = [...threads.getThreads()];
        }
    }
    run(location, transfer, onDone, thread = this._threads[this._count]) {
        const view = Threads.createBinaryTask(16);
        setLocationData(view, location);
        thread.runBinaryTask(this.id, view, onDone);
        this._count++;
        if (this._count >= this._threads.length)
            this._count = 0;
    }
    runAsync(location) {
        return new Promise((resolve) => {
            this.run(location, null, resolve);
        });
    }
    createQueue() {
        return new TaskQueue(this);
    }
}
export class TaskToolTask {
    id;
    _count = 0;
    _threads;
    constructor(id, threads) {
        this.id = id;
        if (threads instanceof Thread) {
            this._threads = [threads];
        }
        else {
            this._threads = [...threads.getThreads()];
        }
    }
    run(data, transfer, onDone) {
        const thread = this._threads[this._count];
        thread.runTask(this.id, data, transfer, onDone);
        this._count++;
        if (this._count >= this._threads.length)
            this._count = 0;
    }
    runAsync(data, transfer) {
        return new Promise((resolve) => {
            this.run(data, transfer, resolve);
        });
    }
    createQueue() {
        return new TaskQueue(this);
    }
}
class VoxelTasks {
    tool;
    paint;
    paintTemplate;
    paintPath;
    erase;
    eraseTemplate;
    eraseSelection;
    erasePath;
    constructor(tool) {
        this.tool = tool;
        this.paint = new TaskToolTask(TasksIds.PaintVoxel, tool.generators);
        this.paintTemplate = new TaskToolTask(TasksIds.PaintVoxelTemplate, tool.generators);
        this.paintPath = new TaskToolTask(TasksIds.PaintVoxelPath, tool.generators);
        this.erase = new TaskToolTask(TasksIds.EraseVoxel, tool.generators);
        this.eraseTemplate = new TaskToolTask(TasksIds.EraseVoxelTemplate, tool.generators);
        this.eraseSelection = new TaskToolTask(TasksIds.EraseVoxelSelection, tool.generators);
        this.erasePath = new TaskToolTask(TasksIds.EraseVoxelPath, tool.generators);
    }
}
class BuildTask {
    tool;
    sectionSnapShot;
    section;
    sector;
    constructor(tool) {
        this.tool = tool;
        this.section = new LocationTaskToolTask(TasksIds.BuildSection, tool.meshers);
        this.sectionSnapShot = new TaskToolTask(TasksIds.BuildSectionSnapShot, tool.meshers);
        this.sector = new LocationTaskToolTask(TasksIds.BuildSector, tool.meshers);
    }
}
class SimulationTasks {
    tool;
    logic;
    propagation;
    constructor(tool) {
        this.tool = tool;
    }
}
class GenerationTasks {
    tool;
    propagation;
    generate;
    decorate;
    worldSun;
    constructor(tool) {
        this.tool = tool;
        this.propagation = new LocationTaskToolTask(TasksIds.WorldPropagation, tool.generators);
        this.generate = new LocationTaskToolTask(TasksIds.Generate, tool.generators);
        this.decorate = new LocationTaskToolTask(TasksIds.Decorate, tool.generators);
        this.worldSun = new LocationTaskToolTask(TasksIds.WorldSun, tool.generators);
    }
}
export class TaskTool {
    meshers;
    generators;
    voxel;
    build;
    generation;
    simulation;
    constructor(meshers, generators) {
        this.meshers = meshers;
        this.generators = generators;
        this.voxel = new VoxelTasks(this);
        this.build = new BuildTask(this);
        this.generation = new GenerationTasks(this);
        this.simulation = new SimulationTasks(this);
    }
    getMesher() {
        if (this.meshers instanceof Thread)
            return this.meshers;
        return this.meshers.nextThread();
    }
    getGenerator() {
        if (this.generators instanceof Thread)
            return this.generators;
        return this.generators.nextThread();
    }
}
